item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score cannot show consistency across runs."
        }
      ],
      "instrument_review": "The puzzle count and scoring rule describe the test, and its intended interpretation is narrow. Repeated-run consistency and the conditions needed for fair system comparisons are not sufficiently documented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run supplies no evidence of score stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "The report clearly documents the absence of repetition. The score describes this evaluation, but consistency across runs remains untested, limiting dependable comparisons."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations under matching conditions directly address changes across runs."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing and an explicit stability criterion support consistency for this system under these conditions. They do not establish consistency under changed conditions or performance beyond the evaluated puzzles."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers directly tested variation across repeated runs under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "The documented variation fails the report's stability criterion. A single 70% result gives an incomplete picture, and comparisons should account for the observed inconsistency."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance does not document repeated-run evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no findings about score consistency."
        }
      ],
      "instrument_review": "Installation instructions explain setup, but do not supply evidence of repeatability or stability. The reported score remains limited to one reported run on these puzzles."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher result on the evaluated puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison fits the stated narrow use. Exact-grid scoring and fixed instructions clarify the comparison, but repeated-run consistency and other resource controls are not reported. Cross-domain conclusions lack supporting evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results show better performance by A on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The intended broad use does not itself provide evidence about performance across domains."
        }
      ],
      "instrument_review": "There is a mismatch between the narrow test content and the intended selection for general intelligence across domains. The results support a puzzle-specific comparison, while evidence for the broader interpretation, consistency, and full comparison controls is missing."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied setting; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness results do not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "Preregistration, random allocation, blinded correctness checking, and reported uncertainty strengthen the later comparison for the intended workshop use. Evidence is limited to correctness in one workshop under the studied conditions; effects on time, safety, and other settings remain unestablished."
    }
  ],
  "closing_note": "No material instruction ambiguity. Missing evidence is classified as Not established; explicit conflicting evidence is classified as Contradicted."
}
